index 0000000..6d57cef
--- /dev/null
+++ b/components/canvas/floating/FloatingImageGenerateContainer.tsx
@@ -0,0 +1,632 @@
+'use client';
+
+import { useCallback, useRef, useEffect, useState } from 'react';
+import { useTranslations, useLocale } from 'next-intl';
+import { toast } from 'sonner';
+import { useQuery } from '@tanstack/react-query';
+
+import { ImageObject, isImageObject } from '@/components/canvas/types';
+import { useFloatingElementPosition } from '@/hooks/use-floating-element-position';
+import { useImageGeneration } from '@/hooks/use-image-generation';
+import { useHistoryState } from '@/hooks/use-history-state';
+import useTokenBalanceData from '@/hooks/use-token-balance-data';
+import { useCanvasTransformStore } from '@/store/canvas-transform-store';
+import { useImageDragStore } from '@/store/image-drag-store';
+import { BaseModelWithRecommendedParameters } from '@/data/base-model';
+import { IMAGE_GENERATION_COST } from '@/constants';
+import { BASE_MODEL_NANO_BANANA_PRO } from '@/constants/image';
+import { createImagePayload } from '@/utils/canvas/image-payload-service';
+import { getImageUrlFromId } from '@/utils/image';
+import {
+  getImageDataUrl,
+  uploadImageBase64DirectToS3
+} from '@/utils/client/image';
+import { CanvasGenerateButton } from '@/components/canvas/canvas-generate-button';
+import { SlidingTabs } from '@/components/sliding-tabs';
+import { Textarea } from '@/components/ui/textarea';
+import { cn } from '@/lib/utils';
+
+const PANEL_WIDTH = 480;
+/** Horizontal gap between original and new image when adding (avoid overlap, but stay in view) */
+const GAP_H = 24;
+/** Vertical offset for new image when adding (small diagonal offset) */
+const GAP_V = 16;
+/** Reference-generate output size (match typical model output to avoid placeholder→final jump) */
+const REFERENCE_OUTPUT_SIZE = 1024;
+
+export interface FloatingImageGenerateContainerProps {
+  open: boolean;
+  onClose: () => void;
+  image: ImageObject | null;
+}
+
+/** Regenerate: image has userPrompt. Reference generate: no prompt (e.g. uploaded), use img2img. */
+function getMode(image: ImageObject | null): 'regenerate' | 'reference-generate' {
+  return image?.userPrompt?.trim() ? 'regenerate' : 'reference-generate';
+}
+
+/**
+ * Resolve reference image ID for img2img: use existing imageIds/imageId, or upload data URL to get id.
+ */
+async function resolveReferenceImageId(image: ImageObject): Promise<{
+  imageId: string;
+  imageUrl: string;
+}> {
+  const existingId =
+    image.imageIds?.[image.currentIndex ?? 0] ?? image.imageId;
+  if (existingId) {
+    const url = await getImageUrlFromId(existingId);
+    if (url) return { imageId: existingId, imageUrl: url };
+  }
+
+  const dataUrl = await getImageDataUrl(image.src);
+  const result = await uploadImageBase64DirectToS3(dataUrl);
+  return { imageId: result.id, imageUrl: result.url || dataUrl };
+}
+
+/** 圖在畫布上的實際顯示寬度（含 scale） */
+function scaledWidth(img: ImageObject): number {
+  return img.width * (img.scaleX ?? 1);
+}
+
+/** 圖在畫布上的實際顯示高度（含 scale） */
+function scaledHeight(img: ImageObject): number {
+  return img.height * (img.scaleY ?? 1);
+}
+
+/** 圖在畫布上的視覺右緣：position.x + 實際寬度 */
+function visualRight(img: ImageObject): number {
+  return img.position.x + scaledWidth(img);
+}
+
+/** 新圖的「中心」座標，讓新圖緊貼在原圖右側（間距 GAP_H），略為下移 GAP_V。hook 會用此中心換算成左上角。會考慮原圖的 scale。 */
+function getNewImagePosition(image: ImageObject) {
+  const rightEdge = visualRight(image);
+  return {
+    x: rightEdge + GAP_H + image.width / 2,
+    y: image.position.y + scaledHeight(image) / 2 + GAP_V
+  };
+}
+
+/** 以指定輸出尺寸計算新圖中心點（避免用原圖寬高導致 placeholder / 最終尺寸不一致時位移） */
+function getNewImagePositionWithOutputSize(
+  image: ImageObject,
+  output: { width: number; height: number }
+) {
+  const rightEdge = visualRight(image);
+  return {
+    x: rightEdge + GAP_H + output.width / 2,
+    y: image.position.y + GAP_V + output.height / 2
+  };
+}
+
+export function FloatingImageGenerateContainer({
+  open,
+  onClose,
+  image
+}: FloatingImageGenerateContainerProps) {
+  const t = useTranslations('Canvas');
+  const tPlain = t as (key: string) => string;
+  const locale = useLocale();
+  const containerRef = useRef<HTMLDivElement>(null);
+  const mode = getMode(image);
+  const isRegenerate = mode === 'regenerate';
+
+  const [prompt, setPrompt] = useState('');
+  /** 'replace' = replace current image; 'add' = add new image to the right */
+  const [replaceOrAdd, setReplaceOrAdd] = useState<'replace' | 'add'>('add');
+  const [isAnalyzingPrompt, setIsAnalyzingPrompt] = useState(false);
+  const hasAutoAnalyzedRef = useRef(false);
+  const analyzeAbortControllerRef = useRef<AbortController | null>(null);
+  const isMountedRef = useRef(true);
+
+  const { updateTempCanvasObjects, commitTempCanvasObjects } =
+    useHistoryState();
+  const { tokenBalance = 0 } = useTokenBalanceData();
+
+  const { data: baseModels } = useQuery({
+    queryKey: ['baseModels'],
+    queryFn: async (): Promise<BaseModelWithRecommendedParameters[]> => {
+      const response = await fetch('/api/base-models');
+      if (!response.ok) throw new Error('Failed to fetch base models');
+      return response.json();
+    }
+  });
+
+  /** 參考生成時使用的模型：優先預設常數，若 API 沒有該模型則用列表第一個，避免沒有模型導致錯誤 */
+  const referenceDefaultModel =
+    baseModels?.some((m) => m.fileName === BASE_MODEL_NANO_BANANA_PRO)
+      ? BASE_MODEL_NANO_BANANA_PRO
+      : (baseModels?.[0]?.fileName ?? BASE_MODEL_NANO_BANANA_PRO);
+
+  const handleAddImage = useCallback(
+    (imageObject: ImageObject, parentId: string | null | undefined) => {
+      // 確保新加入的圖片帶有正確的 parentId（若有的話）
+      const baseImage: ImageObject = {
+        ...imageObject,
+        parentId: parentId ?? imageObject.parentId
+      };
+
+      updateTempCanvasObjects((prev) => {
+        let adjustedImage = baseImage;
+
+        if (replaceOrAdd === 'add') {
+          // 重新生成／參考生成共用：新圖一律接在「原圖右側鏈」末端，形成 原圖 | GAP | 第一張 | GAP | 第二張 | GAP | …
+          const siblingImages = prev.filter(
+            (obj): obj is ImageObject =>
+              isImageObject(obj) && obj.parentId === baseImage.parentId
+          );
+
+          if (siblingImages.length > 0) {
+            const rightMost = siblingImages.reduce((max, curr) => {
+              const maxRight = visualRight(max);
+              const currRight = visualRight(curr);
+              return currRight > maxRight ? curr : max;
+            });
+
+            const refRight =
+              image &&
+              isImageObject(image) &&
+              image.parentId === baseImage.parentId
+                ? visualRight(image)
+                : -Infinity;
+
+            // 原圖 | GAP | 第一張 | GAP | 第二張 | GAP | …；只把「一個 GAP 以內」的 sibling 列入鏈，隔太遠的右側圖不接
+            const CHAIN_GAP = GAP_H;
+            let anchorRight: number;
+            if (refRight > -Infinity) {
+              let rightEdge = refRight;
+              let changed = true;
+              while (changed) {
+                changed = false;
+                for (const s of siblingImages) {
+                  const sLeft = s.position.x;
+                  const sRight = visualRight(s);
+                  if (sLeft >= rightEdge && sLeft <= rightEdge + CHAIN_GAP) {
+                    if (sRight > rightEdge) {
+                      rightEdge = sRight;
+                      changed = true;
+                    }
+                  }
+                }
+              }
+              anchorRight = rightEdge;
+            } else {
+              anchorRight = visualRight(rightMost);
+            }
+
+            adjustedImage = {
+              ...baseImage,
+              position: {
+                x: anchorRight + GAP_H,
+                y:
+                  (image && isImageObject(image)
+                    ? image.position.y
+                    : rightMost.position.y) + GAP_V
+              }
+            };
+          } else if (
+            image &&
+            isImageObject(image) &&
+            image.parentId === baseImage.parentId
+          ) {
+            adjustedImage = {
+              ...baseImage,
+              position: {
+                x: visualRight(image) + GAP_H,
+                y: image.position.y + GAP_V
+              }
+            };
+          }
+        }
+
+        commitTempCanvasObjects({
+          type: 'Added Image',
+          objectId: adjustedImage.id
+        });
+
+        return [...prev, adjustedImage];
+      });
+    },
+    [updateTempCanvasObjects, commitTempCanvasObjects, replaceOrAdd, image]
+  );
+  const handleUpdateImage = useCallback(
+    (updatedImage: ImageObject) => {
+      updateTempCanvasObjects((prev) =>
+        prev.map((obj) => (obj.id === updatedImage.id ? updatedImage : obj))
+      );
+      commitTempCanvasObjects({
+        type: 'Generated Image',
+        objectId: updatedImage.id
+      });
+    },
+    [updateTempCanvasObjects, commitTempCanvasObjects]
+  );
+
+  const { handleParallelGeneration, isGenerating } = useImageGeneration({
+    onAddImage: handleAddImage,
+    onUpdateImage: handleUpdateImage
+  });
+
+  const getTargetObject = useCallback((): ImageObject | undefined => {
+    if (!image || !isImageObject(image)) return undefined;
+    return image;
+  }, [image]);
+
+  const { updatePosition, updatePositionForObject } =
+    useFloatingElementPosition({
+      containerRef,
+      getTargetObject
+    });
+
+  const position = useCanvasTransformStore((state) => state.position);
+  const scale = useCanvasTransformStore((state) => state.scale);
+  const draggingImageId = useImageDragStore((state) => state.draggingImageId);
+  const dragPosition = useImageDragStore((state) => state.dragPosition);
+  const dragDimensions = useImageDragStore((state) => state.dragDimensions);
+  const dragScale = useImageDragStore((state) => state.dragScale);
+  const isDraggingThisImage = image && draggingImageId === image.id;
+
+  useEffect(() => {
+    if (image && open) updatePosition();
+  }, [position.x, position.y, scale, image, open, updatePosition]);
+
+  useEffect(() => {
+    if (image && !isDraggingThisImage) updatePositionForObject(image);
+  }, [
+    image?.position.x,
+    image?.position.y,
+    image?.width,
+    image?.height,
+    image,
+    isDraggingThisImage,
+    updatePositionForObject
+  ]);
+
+  useEffect(() => {
+    if (isDraggingThisImage && image && dragPosition && dragDimensions) {
+      const tempImage: ImageObject = {
+        ...image,
+        position: dragPosition,
+        width: dragDimensions.width,
+        height: dragDimensions.height,
+        scaleX: dragScale?.scaleX ?? image.scaleX ?? 1,
+        scaleY: dragScale?.scaleY ?? image.scaleY ?? 1
+      };
+      updatePositionForObject(tempImage);
+    }
+  }, [
+    isDraggingThisImage,
+    dragPosition,
+    dragDimensions,
+    dragScale,
+    image,
+    updatePositionForObject
+  ]);
+
+  // 管理元件掛載狀態與分析請求的 AbortController，避免 unmount 後仍 setState
+  useEffect(() => {
+    isMountedRef.current = true;
+    return () => {
+      isMountedRef.current = false;
+      if (analyzeAbortControllerRef.current) {
+        analyzeAbortControllerRef.current.abort();
+        analyzeAbortControllerRef.current = null;
+      }
+    };
+  }, []);
+
+  // Sync prompt when panel opens:
+  // - regenerate: 填入原本的 userPrompt，讓使用者可以直接編輯
+  // - reference-generate: 不帶預設提示詞，保持空白（之後由下方 effect 自動分析填入）
+  useEffect(() => {
+    if (!image || !open) return;
+    if (isRegenerate) {
+      const existing = image.userPrompt?.trim();
+      setPrompt(existing && existing.length > 0 ? existing : '');
+    } else {
+      setPrompt('');
+    }
+  }, [image, open, isRegenerate]);
+
+  // 關閉時重置「已自動分析」標記，下次打開參考生成會再自動分析一次
+  useEffect(() => {
+    if (!open) hasAutoAnalyzedRef.current = false;
+  }, [open]);
+
+  const runReferenceGenerate = useCallback(
+    async (promptText: string, replaceCurrent: boolean) => {
+      if (!image) return;
+      const safePrompt =
+        promptText.trim() ||
+        tPlain('quickActions.referenceGenerateDefaultPrompt').trim();
+      const baseModel = referenceDefaultModel;
+      const outputSize = { width: REFERENCE_OUTPUT_SIZE, height: REFERENCE_OUTPUT_SIZE };
+      const position = replaceCurrent
+        ? { x: image.position.x + image.width / 2, y: image.position.y + image.height / 2 }
+        : getNewImagePositionWithOutputSize(image, outputSize);
+      const target = replaceCurrent
+        ? { type: 'image' as const, imageToReplace: image }
+        : { type: 'image' as const, panel: null, imageToReplace: null as null };
+      const { imageId: referenceImageId, imageUrl } =
+        await resolveReferenceImageId(image);
+      const payload = createImagePayload({
+        baseModel,
+        seed: Math.floor(Math.random() * 1_000_000_000),
+        width: outputSize.width,
+        height: outputSize.height,
+        prompt: safePrompt,
+        selectedCharacter: null,
+        numberOfImages: 1,
+        steps: 20,
+        loras: [],
+        cfgScale: 7,
+        clipSkip: 1,
+        negativePrompt: '',
+        denoisingStrength: 0.75,
+        samplerName: 'euler',
+        scheduler: 'simple',
+        inputImage: imageUrl,
+        inputImageId: referenceImageId
+      });
+      const modelCostPerImage =
+        baseModels?.find((m) => m.fileName === baseModel)?.tokenCost ??
+        undefined;
+
+      await handleParallelGeneration({
+        panelId: image.parentId ?? null,
+        prompt: safePrompt,
+        width: outputSize.width,
+        height: outputSize.height,
+        position,
+        baseModel,
+        payload,
+        target,
+        numberOfImages: 1,
+        originalTokenCount: tokenBalance,
+        costPerImage: modelCostPerImage,
+        referenceImageIds: [referenceImageId]
+      });
+    },
+    [image, baseModels, tokenBalance, handleParallelGeneration, referenceDefaultModel, t]
+  );
+
+  const handleSubmit = useCallback(async () => {
+    if (!image) return;
+    const promptText = prompt.trim();
+    const effectivePrompt = isRegenerate
+      ? (promptText || image.userPrompt?.trim() || '')
+      : promptText || '';
+
+    // 重新生成與參考生成皆必填提示詞
+    if (!effectivePrompt) {
+        toast.error(tPlain('generateInfo.error.promptRequired'));
+      return;
+    }
+
+    try {
+      const baseModel =
+        isRegenerate && image.baseModel
+          ? image.baseModel
+          : BASE_MODEL_NANO_BANANA_PRO;
+      const replaceCurrent = replaceOrAdd === 'replace';
+      const outputSize = isRegenerate
+        ? { width: image.width, height: image.height }
+        : { width: REFERENCE_OUTPUT_SIZE, height: REFERENCE_OUTPUT_SIZE };
+      const position = replaceCurrent
+        ? { x: image.position.x + image.width / 2, y: image.position.y + image.height / 2 }
+        : isRegenerate
+          ? getNewImagePosition(image)
+          : getNewImagePositionWithOutputSize(image, outputSize);
+      const target = replaceCurrent
+        ? { type: 'image' as const, imageToReplace: image }
+        : { type: 'image' as const, panel: null, imageToReplace: null as null };
+
+      if (isRegenerate) {
+        const { imageId: referenceImageId, imageUrl } =
+          await resolveReferenceImageId(image);
+        const payload = createImagePayload({
+          baseModel,
+          seed: image.seed ?? Math.floor(Math.random() * 1_000_000_000),
+          width: image.width,
+          height: image.height,
+          prompt: effectivePrompt,
+          selectedCharacter: image.generatedWithCharacter ?? null,
+          numberOfImages: 1,
+          steps: image.steps ?? 20,
+          loras: image.loras ?? [],
+          cfgScale: image.cfgScale ?? 7,
+          clipSkip: image.clipSkip ?? 1,
+          negativePrompt: image.negativePrompt ?? '',
+          denoisingStrength: image.denoisingStrength ?? 0.75,
+          samplerName: image.samplerName ?? 'euler',
+          scheduler: image.scheduler ?? 'simple',
+          inputImage: imageUrl,
+          inputImageId: referenceImageId
+        });
+        const modelCostPerImage =
+          baseModels?.find((m) => m.fileName === baseModel)?.tokenCost ??
+          undefined;
+
+        await handleParallelGeneration({
+          panelId: image.parentId ?? null,
+          prompt: effectivePrompt,
+          width: image.width,
+          height: image.height,
+          position,
+          baseModel,
+          payload,
+          target,
+          numberOfImages: 1,
+          originalTokenCount: tokenBalance,
+          costPerImage: modelCostPerImage,
+          referenceImageIds: [referenceImageId]
+        });
+      } else {
+        await runReferenceGenerate(effectivePrompt, replaceCurrent);
+      }
+
+      onClose();
+    } catch (err) {
+      console.error('Image generate failed', err);
+      toast.error(tPlain('quickActions.imageGenerateFailed'));
+    }
+  }, [
+    prompt,
+    image,
+    isRegenerate,
+    replaceOrAdd,
+    baseModels,
+    tokenBalance,
+    handleParallelGeneration,
+    runReferenceGenerate,
+    onClose,
+    tPlain
+  ]);
+
+  const handleAnalyzeAndFillPrompt = useCallback(async () => {
+    if (!image) return;
+    // 取消前一次尚未完成的分析請求
+    if (analyzeAbortControllerRef.current) {
+      analyzeAbortControllerRef.current.abort();
+    }
+    const controller = new AbortController();
+    analyzeAbortControllerRef.current = controller;
+    setIsAnalyzingPrompt(true);
+    try {
+      const imageId =
+        image.imageIds?.[image.currentIndex ?? 0] ?? image.imageId ?? undefined;
+      const body: { targetLocale: string; imageId?: string; imageDataUrl?: string } = {
+        targetLocale: locale
+      };
+      if (imageId) {
+        body.imageId = imageId;
+      } else {
+        body.imageDataUrl = await getImageDataUrl(image.src);
+      }
+      const res = await fetch('/api/canvas/describe-image', {
+        method: 'POST',
+        headers: { 'Content-Type': 'application/json' },
+        body: JSON.stringify(body),
+        signal: controller.signal
+      });
+      if (!isMountedRef.current || analyzeAbortControllerRef.current !== controller) {
+        return;
+      }
+      const data = await res.json();
+      if (!res.ok) {
+        toast.error(
+          data?.error ??
+            tPlain('quickActions.analyzePromptFailed')
+        );
+        return;
+      }
+      if (typeof data?.prompt === 'string') {
+        setPrompt(data.prompt);
+        toast.success(
+          tPlain('quickActions.analyzePromptSuccess')
+        );
+      }
+    } catch (err) {
+      if (!isMountedRef.current || controller.signal.aborted) {
+        return;
+      }
+      console.error('Analyze prompt failed', err);
+      toast.error(
+        tPlain('quickActions.analyzePromptFailed')
+      );
+    } finally {
+      if (isMountedRef.current && analyzeAbortControllerRef.current === controller) {
+        setIsAnalyzingPrompt(false);
+        analyzeAbortControllerRef.current = null;
+      }
+    }
+  }, [image, locale, tPlain]);
+
+  // 參考生成模式：打開時自動呼叫 AI 分析圖片並填入提示詞（僅執行一次）
+  useEffect(() => {
+    if (!open || !image || isRegenerate || hasAutoAnalyzedRef.current) return;
+    hasAutoAnalyzedRef.current = true;
+    handleAnalyzeAndFillPrompt();
+  }, [open, image, isRegenerate, handleAnalyzeAndFillPrompt]);
+
+  const visible = open && !!image;
+
+  if (!visible) return null;
+  if (!image) return null;
+
+  const placeholder = isRegenerate
+    ? tPlain('quickActions.regeneratePlaceholder')
+    : isAnalyzingPrompt
+      ? tPlain('quickActions.analyzePromptLoading')
+      : tPlain('quickActions.referenceGeneratePlaceholder');
+  const submitLabel = isRegenerate
+    ? t('quickActions.regenerate')
+    : t('quickActions.referenceGenerateSubmit');
+
+  const baseModelForCost = isRegenerate
+    ? (image.baseModel ?? BASE_MODEL_NANO_BANANA_PRO)
+    : referenceDefaultModel;
+  const costPerImage = baseModels?.find(
+    (m) => m.fileName === baseModelForCost
+  )?.tokenCost;
+
+  return (
+    <div
+      ref={containerRef}
+      className={cn(
+        'fixed z-20 flex flex-col gap-1 p-3 rounded-lg',
+        'border border-gray-200 shadow-lg bg-white',
+        'transition-opacity duration-150',
+        '-translate-x-1/2',
+        'bg-background/60 backdrop-blur-md border-border'
+      )}
+      style={{
+        width: `${PANEL_WIDTH}px`,
+        left: '-9999px',
+        top: '-9999px'
+      }}
+    >
+      <Textarea
+        value={prompt}
+        onChange={(e) => setPrompt(e.target.value)}
+        placeholder={placeholder}
+        className="resize-none text-sm min-h-[60px] max-h-[120px] mb-2"
+        disabled={isGenerating || isAnalyzingPrompt}
+      />
+      <div className="flex items-center gap-2">
+        <div className="flex items-center gap-2 min-w-0 flex-1">
+          <span className="text-xs text-muted-foreground whitespace-nowrap">
+            {t('quickActions.outputMode')}
+          </span>
+          <SlidingTabs
+            value={replaceOrAdd}
+            onValueChange={(v) => {
+              if (v === 'replace' || v === 'add') setReplaceOrAdd(v);
+            }}
+            items={[
+              { value: 'replace', label: t('quickActions.replaceImage') },
+              { value: 'add', label: t('quickActions.addNewImage') }
+            ]}
+            size="sm"
+            className="flex-1 min-w-0"
+            listClassName="flex-1 justify-center"
+          />
+        </div>
+        <CanvasGenerateButton
+          size="sm"
+          handleGenerate={handleSubmit}
+          isGenerating={isGenerating}
+          disabled={
+            isGenerating ||
+            isAnalyzingPrompt ||
+            !prompt.trim()
+          }
+          costPerImage={costPerImage ?? IMAGE_GENERATION_COST}
+          labelText={submitLabel}
+          className="flex-shrink-0 w-auto"
+        />
+      </div>
+    </div>
+  );
+}
