+// 每位使用者限制：每分鐘最多 30 次 describe-image 呼叫，避免無成本濫用 Gemini API
+const describeImageRateLimiter = createRateLimiter({
+  limit: 30,
+  windowInSeconds: 60
+});
+
+const DescribeImageRequestSchema = z.object({
+  /** 已有 image 記錄時傳入，伺服器會依此取得圖片並分析 */
+  imageId: z.string().uuid().or(z.string().cuid()).optional(),
+  /** 無 imageId 時可傳 base64 data URL（例如畫布上貼上/拖入的圖） */
+  imageDataUrl: z
+    .string()
+    // 以字元長度近似限制 data URL 大小，避免超大 payload 造成記憶體壓力
+    .max(10_000_000, 'imageDataUrl is too large')
+    .optional(),
+  targetLocale: z.string().min(1, 'Target locale is required')
+});
+
+/**
+ * POST /api/canvas/describe-image
+ *
+ * 使用 AI 分析單張圖片並產生適合圖生圖的提示詞。
+ * 用於 Canvas 參考生圖時自動填入提示詞。
+ *
+ * @body {string} [imageId] - 圖片 ID（與 imageDataUrl 二擇一）
+ * @body {string} [imageDataUrl] - 圖片 data URL（與 imageId 二擇一）
+ * @body {string} targetLocale - 目標語系（en, ja, zh-TW 等）
+ * @returns { prompt: string, success: true } | { error: string }
+ */
+export async function POST(req: NextRequest) {
+  const user = await currentUser();
+  if (!user) {
+    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
+  }
+
+  // per-user rate limit：限制單一使用者在時間窗內的請求數量
+  const rateLimitKey = `canvas:describe-image:user:${user.id}`;
+  const rateLimitResult = await describeImageRateLimiter(rateLimitKey);
+  if (!rateLimitResult.success) {
+    logger.warn('Canvas describe-image rate limit exceeded', {
+      userId: user.id,
+      limit: rateLimitResult.limit,
+      reset: rateLimitResult.reset
+    });
+    return NextResponse.json(
+      {
+        error: 'Rate limit exceeded. Please try again later.',
+        limit: rateLimitResult.limit,
+        reset: rateLimitResult.reset
+      },
+      {
+        status: 429,
+        headers: {
+          'X-RateLimit-Limit': rateLimitResult.limit.toString(),
+          'X-RateLimit-Remaining': rateLimitResult.remaining.toString(),
+          'X-RateLimit-Reset': rateLimitResult.reset.toString()
+        }
+      }
+    );
+  }
+
+  let body: unknown;
+  try {
+    body = await req.json();
+  } catch {
+    return NextResponse.json(
+      { error: 'Invalid request format' },
+      { status: 400 }
+    );
+  }
+
+  const parsed = DescribeImageRequestSchema.safeParse(body);
+  if (!parsed.success) {
+    return NextResponse.json(
+      { error: 'Invalid parameters', details: parsed.error.flatten() },
+      { status: 400 }
+    );
+  }
+
+  const { imageId, imageDataUrl, targetLocale } = parsed.data;
+
+  if (!imageId && !imageDataUrl) {
+    return NextResponse.json(
+      { error: 'Either imageId or imageDataUrl is required' },
+      { status: 400 }
+    );
+  }
+  if (imageId && imageDataUrl) {
+    return NextResponse.json(
+      { error: 'Provide only one of imageId or imageDataUrl' },
+      { status: 400 }
+    );
+  }
+
+  try {
+    let imageUrlForPrompt: string;
+
+    if (imageId) {
+      const imageData = await getImage(imageId, user.id);
+      if (!imageData.rawUrl) {
+        return NextResponse.json(
+          { error: 'Image has no valid URL' },
+          { status: 400 }
+        );
+      }
+      imageUrlForPrompt = await urlToBase64(imageData.rawUrl);
+    } else if (imageDataUrl) {
+      if (!imageDataUrl.startsWith('data:')) {
+        return NextResponse.json(
+          { error: 'imageDataUrl must be a data URL' },
+          { status: 400 }
+        );
+      }
+      imageUrlForPrompt = imageDataUrl;
+    } else {
+      return NextResponse.json(
+        { error: 'Missing image source' },
+        { status: 400 }
+      );
+    }
+
+    const prompt = await mergeMultiImagePrompts(
+      [imageUrlForPrompt],
+      targetLocale,
+      undefined
+    );
+
+    logger.info('Canvas describe-image succeeded', {
+      targetLocale,
+      promptLength: prompt.length,
+      source: imageId ? 'imageId' : 'imageDataUrl'
+    });
+
+    return NextResponse.json({ prompt, success: true });
+  } catch (err) {
+    logger.error(
+      'Canvas describe-image failed',
+      err instanceof Error ? err : { cause: String(err) },
+      { targetLocale }
+    );
+    return NextResponse.json(
+      { error: 'Failed to describe image' },
+      { status: 500 }
+    );
+  }
+}
