@@ -8,6 +8,30 @@ import { getMimeTypeFromDataUrl } from '@/utils/image';

 const logger = createLogger('utils/client/image');

+/**
+ * 取得圖片的 data URL。若已是 data URL 則直接回傳；若為 http(s) URL 則 fetch 後轉成 data URL。
+ * 僅支援 client 端（使用 fetch、FileReader）。
+ * @param src 圖片來源（單一 URL 或陣列，取第一個）
+ * @returns data URL
+ * @throws Error 當無來源或為不支援的來源類型
+ */
+export async function getImageDataUrl(src: string | string[]): Promise<string> {
+  const url = Array.isArray(src) ? src[0] : src;
+  if (!url) throw new Error('Image has no source');
+  if (url.startsWith('data:')) return url;
+  if (url.startsWith('http://') || url.startsWith('https://')) {
+    const res = await fetch(url);
+    const blob = await res.blob();
+    return new Promise((resolve, reject) => {
+      const reader = new FileReader();
+      reader.onloadend = () => resolve(reader.result as string);
+      reader.onerror = reject;
+      reader.readAsDataURL(blob);
+    });
+  }
+  throw new Error('Unsupported image source');
+}
